const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let config,accessToken=localStorage.getItem('lm_access_token')||'',brands=[],period='weekly';
const fmt=n=>'Rp '+Math.round(Number(n)||0).toLocaleString('id-ID'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){const t=$('#toast');if(t){t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}}
async function api(path,options={}){const res=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(accessToken?{Authorization:`Bearer ${accessToken}`}:{ }),...(options.headers||{})}});if(res.status===204)return null;const data=await res.json();if(!res.ok)throw Error(data.error||`HTTP ${res.status}`);return data}
function profile(){let name=localStorage.getItem('lm_user')||'Admin';$('#userName').textContent=name.split('@')[0];$('#userType').textContent='Admin · Supabase';$('#avatar').textContent=(name[0]||'A').toUpperCase();$('#adminbar').classList.add('visible');$('#loginBtn').style.display='none'}
function updateAccess(){const admin=!!accessToken;$$('.nav button').forEach(b=>{b.disabled=!admin&&b.dataset.page!=='dashboard';b.style.opacity=b.disabled?'.45':''});if(!admin&&$('.page.active')?.id!=='page-dashboard')navigate('dashboard');if(admin)profile();else{$('#adminbar').classList.remove('visible');$('#loginBtn').style.display=''}}
function navigate(page){if(page!=='dashboard'&&!accessToken){toast('Login admin diperlukan');page='dashboard'}$$('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$$('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+page));$('#crumb').textContent=page==='brands'?'Data brand':page==='social'?'Insight sosial':'Dashboard';$('#sidebar').classList.remove('open')}
async function load(){try{const a=await api('/api/brands');brands=a.brands||[];renderBrands();const now=new Date(),end=now.toISOString().slice(0,10),days=period==='daily'?1:period==='monthly'?30:7,start=new Date(now.getTime()-(days-1)*864e5).toISOString().slice(0,10);const d=await api(`/api/dashboard?start=${start}&end=${end}`);renderDashboard(d);renderSocial()}catch(e){toast(e.message)}}
function renderDashboard(d){const t=d.totals||{};const cards=[['Total spend budget',fmt(t.spend),'↗',0,'Data Meta tersinkron'],['Klik tautan',Number(t.clicks||0).toLocaleString('id-ID'),'⌁',0,'Jumlah klik iklan'],['CTR rata-rata',`${t.impressions?((t.clicks||0)*100/t.impressions).toFixed(2):'0.00'}%`,'◉',0,'Klik ÷ impresi'],['Visitor website','—','⌖',0,'Perlu integrasi GA4']];$('#stats').innerHTML=cards.map(([l,v,ic])=>`<article class="stat"><div class="stathead">${l}<span class="stat-icon">${ic}</span></div><div class="value">${v}</div><div class="delta neutral">${l==='Visitor website'?'Belum tersedia':'Periode terpilih'}</div></article>`).join('');$('#rangeLabel').textContent=`${d.start} – ${d.end}`;$('#chartPeriod').textContent=period==='daily'?'Hari ini':period==='monthly'?'30 hari terakhir':'7 hari terakhir';$('#brandRows').innerHTML=(d.brands||[]).map(b=>`<tr><td><div class="brand-cell"><span class="branddot">${esc(b.short_name||b.name.slice(0,2))}</span>${esc(b.name)}</div></td><td>${fmt(b.spend)}</td><td>${Number(b.clicks||0).toLocaleString('id-ID')}</td><td>${Number(b.ctr||0).toFixed(2)}%</td><td>—</td><td><span class="delta neutral">—</span></td><td><span class="status ${b.connected?'live':'attn'}">${b.connected?'Terhubung':'Belum terhubung'}</span></td></tr>`).join('');$('.chart').innerHTML='<div class="muted" style="padding:50px 20px">Grafik mengisi setelah data Meta masuk.</div>';$('#bars').innerHTML='<div class="muted">Grafik mengisi setelah data Meta masuk.</div>';const notice=$('.notice');if(notice)notice.innerHTML=`<span class="i">●</span><div><strong>Dashboard data aktual.</strong> ${esc(d.note||'')}</div>`}
function renderBrands(){const q=($('#brandSearch')?.value||'').toLowerCase(),filtered=brands.filter(b=>b.name.toLowerCase().includes(q)),isAdmin=!!accessToken;$('#brandCount').textContent=`${brands.length} brand`;$('#addBrand').style.display=isAdmin?'':'none';$('#brandList').innerHTML=filtered.map(b=>`<div class="brand-row"><div class="brand-info"><span class="branddot" style="width:36px;height:36px">${esc(b.short_name||b.name.slice(0,2))}</span><div><b>${esc(b.name)}</b><small>${isAdmin&&b.meta_connections?.length?esc(b.meta_connections.map(c=>c.ad_account_name).join(', ')):'Brand'}</small></div></div>${isAdmin?`<div class="brand-actions"><button class="btn small connect" data-id="${b.id}">Sambungkan Meta</button><button class="btn small edit-brand" data-id="${b.id}">Ubah nama</button><button class="btn small remove" data-id="${b.id}">Hapus</button></div>`:''}</div>`).join('')||'<div class="brand-row">Belum ada brand.</div>';$$('.connect').forEach(x=>x.onclick=async()=>{try{const result=await api(`/api/meta/connect/${encodeURIComponent(x.dataset.id)}`);location.href=result.url}catch(e){toast(e.message)}});$$('.edit-brand').forEach(x=>x.onclick=()=>editBrand(x.dataset.id));$$('.remove').forEach(x=>x.onclick=async()=>{if(confirm('Hapus brand ini dan seluruh data terkait?')){await api(`/api/brands/${x.dataset.id}`,{method:'DELETE'});await load()}})}
function renderSocial(){const selected=brands.slice(0,4);$('#socialCards').innerHTML=selected.map(b=>`<div class="social-card"><div class="socialbrand"><span class="socialicon">◎</span>${esc(b.name)}</div><div class="socialnumbers"><div><b>—</b><small>Reach</small></div><div><b>—</b><small>Interaksi</small></div><div><b>—</b><small>Engagement</small></div></div><div class="connectbar"><span class="status attn">Belum tersedia</span><span class="muted">Instagram</span></div></div>`).join('');$('#socialRows').innerHTML=selected.map(b=>`<tr><td>${esc(b.name)}</td><td>Instagram</td><td>—</td><td>—</td><td>—</td><td><span class="status attn">Belum terhubung</span></td></tr>`).join('')}
function modal(title,desc,html,submit){$('#modalTitle').textContent=title;$('#modalDesc').textContent=desc;$('#modalBody').innerHTML=html;$('#modal').classList.add('open');if(submit)$('#modalSubmit').onclick=submit}function closeModal(){$('#modal').classList.remove('open')}
function editBrand(id){const b=brands.find(x=>x.id===id);modal('Ubah nama brand','Perubahan akan tersimpan untuk semua admin.',`<div class="field"><label>Nama brand</label><input id="editName" value="${esc(b.name)}"></div><div class="field"><label>Singkatan</label><input id="editTag" maxlength="3" value="${esc(b.short_name||'')}"></div><div class="modal-actions"><button class="btn" id="cancel">Batal</button><button class="btn primary" id="modalSubmit">Simpan</button></div>`,async()=>{try{await api(`/api/brands/${id}`,{method:'PATCH',body:JSON.stringify({name:$('#editName').value,short_name:$('#editTag').value})});closeModal();await load()}catch(e){toast(e.message)}});$('#cancel').onclick=closeModal}
function login(){modal('Masuk sebagai admin','Autentikasi dikelola oleh Supabase.',`<div class="authchoice"><button class="btn" id="googleLogin">Lanjutkan dengan Google</button></div><div style="text-align:center;color:#758296;font-size:11px">atau email / nomor telepon dan password</div><div class="field"><label>Email atau nomor telepon</label><input id="email" placeholder="nama@perusahaan.com"></div><div class="field"><label>Password</label><input id="password" type="password"></div><div class="modal-actions"><button class="btn primary" id="modalSubmit">Masuk</button></div>`,async()=>{try{const ident=$('#email').value.trim(),pass=$('#password').value;if(!ident||!pass)return toast('Isi email/nomor dan password');const phone=/^\+?[0-9 ()-]{8,}$/.test(ident);const res=await fetch(`${config.supabaseUrl}/auth/v1/token?grant_type=password`,{method:'POST',headers:{'Content-Type':'application/json','apikey':config.supabaseAnonKey},body:JSON.stringify(phone?{phone:ident,password:pass}:{email:ident,password:pass})});const data=await res.json();if(!res.ok)throw Error(data.msg||data.message||data.error_description||'Login gagal');const pr=await fetch('/api/profile',{headers:{Authorization:`Bearer ${data.access_token}`}}).then(r=>r.json());if(pr.profile?.role!=='admin')throw Error('Akun ini belum mendapat akses admin. Hubungi pemilik workspace.');accessToken=data.access_token;localStorage.setItem('lm_access_token',accessToken);localStorage.setItem('lm_user',ident);closeModal();updateAccess();await load();toast('Login berhasil')}catch(e){toast(e.message)}});$('#googleLogin').onclick=()=>{location.href=`${config.supabaseUrl}/auth/v1/authorize?provider=google&redirect_to=${encodeURIComponent(location.origin)}`}}
$('#loginBtn').onclick=login;$('#closeModal').onclick=closeModal;$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};$('#logoutBtn').onclick=()=>{accessToken='';localStorage.removeItem('lm_access_token');localStorage.removeItem('lm_user');updateAccess();navigate('dashboard');toast('Anda keluar')};$$('.nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$$('[data-goto]').forEach(b=>b.onclick=()=>navigate(b.dataset.goto));$('#period').onchange=e=>{period=e.target.value;load()};$('#brandSearch').oninput=renderBrands;$('#hamb').onclick=()=>$('#sidebar').classList.toggle('open');$('#addBrand').onclick=()=>modal('Tambah brand','Brand tersimpan di database bersama.',`<div class="field"><label>Nama brand</label><input id="newName"></div><div class="field"><label>Singkatan</label><input id="newTag" maxlength="3"></div><div class="modal-actions"><button class="btn" id="cancel">Batal</button><button class="btn primary" id="modalSubmit">Tambah brand</button></div>`,async()=>{try{await api('/api/brands',{method:'POST',body:JSON.stringify({name:$('#newName').value,short_name:$('#newTag').value})});closeModal();await load()}catch(e){toast(e.message)}});$('#connectInstagram').onclick=()=>toast('Instagram Insights belum diaktifkan pada backend ini');$('#exportBtn').onclick=()=>toast('Ekspor laporan akan tersedia setelah integrasi dashboard lengkap');
async function init(){try{config=await api('/api/config');const badge=$('.demo-pill');if(badge)badge.textContent='● META INSIGHT';if(location.hash.includes('access_token=')){const p=new URLSearchParams(location.hash.slice(1));const candidate=p.get('access_token')||'';if(candidate){const pr=await fetch('/api/profile',{headers:{Authorization:`Bearer ${candidate}`}}).then(r=>r.json());if(pr.profile?.role==='admin'){accessToken=candidate;localStorage.setItem('lm_access_token',accessToken);localStorage.setItem('lm_user',pr.user.email||pr.user.phone||'Admin')}else toast('Akun ini belum mendapat akses admin');history.replaceState(null,'',location.pathname)}}if(accessToken){const pr=await fetch('/api/profile',{headers:{Authorization:`Bearer ${accessToken}`}}).then(r=>r.json());if(pr.profile?.role!=='admin'){accessToken='';localStorage.removeItem('lm_access_token');localStorage.removeItem('lm_user')}}updateAccess();await load()}catch(e){toast(e.message)}}init();
